{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The 'enable_https_traffic_only' property is set to false, which allows unencrypted HTTP traffic. This increases the risk of data interception."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The 'min_tls_version' is set to 'TLS1_0', which is outdated and vulnerable. Using the latest TLS version ensures stronger encryption."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Blob anonymous access is not explicitly disabled, which could allow unauthorized access to blob data."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Ensure soft-delete is enabled on Azure storage account",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Soft-delete for blobs is not enabled, which means deleted data cannot be recovered, increasing the risk of data loss."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n\n  blob_properties {\n    versioning_enabled = true\n    delete_retention_policy {\n      days = 7\n    }\n  }\n\n  allow_blob_public_access = false\n}",
  "fix_summary": "Enabled HTTPS traffic only, updated TLS version to TLS1_2, disabled blob anonymous access, and enabled soft-delete with a retention period of 7 days."
}
